/*! Minimal shim to load Select2 from CDN if local file missing */
(function(){
    try {
        if (window.jQuery && typeof window.jQuery.fn.select2 === 'function') return; // already loaded
        var s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js';
        s.onload = function(){ console && console.log && console.log('Select2 loaded from CDN fallback'); };
        s.onerror = function(){ console && console.error && console.error('Failed to load Select2 from CDN'); };
        document.head.appendChild(s);
    } catch(e) { console && console.error && console.error(e); }
})();
